'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(){const c={window:{}};vm.createContext(c);for(const f of ['white-orchard.js','progression-data.js','progression-engine.js','departure.js','warning-details.js','warning-center.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);const w=c.window,{tasks,hubs}=w.PHOENIX_ROUTE,engine=w.createPhoenixProgress(w.PHOENIX_PROGRESS_DATA,tasks,hubs),state={progress:engine.init(),completed:{}};return {state,tasks,engine,get(hash){return w.PhoenixWarningCenterModel.build({state,tasks,engine,hash})}};}
test('fresh risks have canonical identity, verification and cutoff order without changing records',()=>{const x=setup(),before=JSON.stringify(x.state),v=x.get('#home');assert.deepEqual(Array.from(v.items,i=>i.id),['poi-4','q-firestarter','q-missing','q-death']);assert.equal(v.count,4);assert.equal(v.final,false);assert.ok(v.items.every(i=>i.unknown&&i.verify&&i.cutoff));assert.equal(JSON.stringify(x.state),before)});
test('FINAL applies only to relevant actual cutoff steps, never ordinary browsing',()=>{const x=setup();assert.equal(x.get('#'+x.tasks['q-lilac'].view+'/1').final,false);assert.equal(x.get('#'+x.tasks['q-beast'].view+'/trophy').final,true);const d=x.get('#'+x.tasks['q-lilac'].view+'/4');assert.equal(d.items.filter(i=>i.final).length,3);assert.equal(d.items[0].final,false)});
test('resolved outcomes disappear, uncertain passed cutoffs remain unknown without FINAL',()=>{const x=setup();x.state.completed['poi-4']=true;x.state.progress.legacy['q-firestarter']=true;x.state.progress.failed['q-missing']=true;let v=x.get('#home');assert.deepEqual(Array.from(v.items,i=>i.id),['q-death']);x.state.progress.manual.departed=true;v=x.get('#'+x.tasks['q-incident'].view+'/1');assert.equal(v.count,1);assert.equal(v.items[0].unknown,true);assert.equal(v.final,false)});
test('progress correction quietly restores the same canonical risk',()=>{const x=setup();for(const q of ['q-firestarter','q-missing','q-death'])x.state.progress.legacy[q]=true;x.state.completed['poi-4']=true;assert.equal(x.get('#home').count,0);delete x.state.progress.legacy['q-death'];const v=x.get('#home');assert.equal(v.count,1);assert.equal(v.final,false);assert.equal(v.items[0].id,'q-death')});

test('final summary and shared illustrations derive from canonical risks without writing saves',()=>{const x=setup(),before=JSON.stringify(x.state),v=x.get('#'+x.tasks['q-lilac'].view+'/4');assert.equal(v.finalCount,3);assert.equal(v.count,4);for(const item of v.items){assert.ok(fs.existsSync(item.art));assert.ok(item.consequence.length>20);}assert.equal(JSON.stringify(x.state),before);x.state.progress.manual.departed=true;assert.equal(x.get('#'+x.tasks['q-incident'].view+'/1').finalCount,0);});
